const STORAGE_KEY = 'freshtrace_bio_state_v3';
const DEFAULT_PUBLIC_BASE_URL = 'https://dhasleemadevi-dotcom.github.io/anthofresh-iot/';
const nowISO = () => new Date().toISOString();
const fmtDateTime = (iso) => iso ? new Intl.DateTimeFormat('en-IN',{dateStyle:'medium',timeStyle:'short'}).format(new Date(iso)) : '—';
const fmtDate = (v) => v ? new Intl.DateTimeFormat('en-IN',{dateStyle:'medium'}).format(new Date(v)) : '—';
const dateOnly = (d) => { const x=new Date(d); return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`; };
const dateTimeLocalISO = (date,time='12:00') => `${date}T${time}:00`;
const addDays=(dateOrDate,days)=>{const d=new Date(dateOrDate);d.setDate(d.getDate()+days);return dateOnly(d)};
const daysBetween=(a,b)=>Math.max(0,(new Date(b)-new Date(a))/(1000*60*60*24));

const PRODUCT_PROFILES = {
  'Meat': {shelfDays:3, idealTemp:4, pH:{Fresh:5.8,Early:6.7,Moderate:7.3,High:8.0}, gas:{Fresh:12,Early:34,Moderate:62,High:82}, contamination:{Fresh:'Very Low',Early:'Low',Moderate:'Moderate',High:'High'}, condition:{Fresh:'Fresh & chilled',Early:'Early spoilage indication',Moderate:'Moderate spoilage indication',High:'High spoilage indication'}},
  'Dairy': {shelfDays:4, idealTemp:4, pH:{Fresh:6.6,Early:6.9,Moderate:7.2,High:7.6}, gas:{Fresh:10,Early:30,Moderate:54,High:78}, contamination:{Fresh:'Very Low',Early:'Low',Moderate:'Moderate',High:'High'}, condition:{Fresh:'Fresh & refrigerated',Early:'Early spoilage indication',Moderate:'Moderate spoilage indication',High:'High spoilage indication'}},
  'Bakery': {shelfDays:5, idealTemp:22, pH:{Fresh:5.5,Early:5.9,Moderate:6.3,High:6.8}, gas:{Fresh:8,Early:24,Moderate:48,High:72}, contamination:{Fresh:'Very Low',Early:'Low',Moderate:'Moderate',High:'High'}, condition:{Fresh:'Fresh bakery product',Early:'Early spoilage indication',Moderate:'Moderate spoilage indication',High:'High spoilage indication'}},
  'Ready-to-Eat': {shelfDays:3, idealTemp:4, pH:{Fresh:5.8,Early:6.4,Moderate:7.1,High:7.8}, gas:{Fresh:14,Early:35,Moderate:60,High:84}, contamination:{Fresh:'Very Low',Early:'Low',Moderate:'Moderate',High:'High'}, condition:{Fresh:'Fresh chilled meal',Early:'Early spoilage indication',Moderate:'Moderate spoilage indication',High:'High spoilage indication'}}
};
const STAGES = ['Fresh','Early Spoilage','Moderate Spoilage','High Indication'];
const STAGE_SHORT = {Fresh:'Fresh', 'Early Spoilage':'Early', 'Moderate Spoilage':'Moderate', 'High Indication':'High'};
const COLOR_FOR_STAGE = {Fresh:'Purple','Early Spoilage':'Yellow','Moderate Spoilage':'Green','High Indication':'Red'};
const STAGE_FROM_COLOR = {Purple:'Fresh',Yellow:'Early Spoilage',Green:'Moderate Spoilage',Red:'High Indication'};

function stageInfo(stage){
  const map={
    Fresh:{color:'#9B43E5',bg:'#26123A',soft:'#ECDDFF',symbol:'🟣',label:'Fresh',class:'status-purple'},
    'Early Spoilage':{color:'#E6BE38',bg:'#3A3111',soft:'#FFF3BD',symbol:'🟡',label:'Early Spoilage',class:'status-yellow'},
    'Moderate Spoilage':{color:'#47C786',bg:'#0D3424',soft:'#DDF8EA',symbol:'🟢',label:'Moderate Spoilage',class:'status-green'},
    'High Indication':{color:'#E4546D',bg:'#391620',soft:'#FFE3E8',symbol:'🔴',label:'High Indication',class:'status-red'}
  }; return map[stage]||map.Fresh;
}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function fileToDataURL(file){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});}
function demoDate(daysOffset, time='10:30'){const d=new Date();d.setDate(d.getDate()+daysOffset);return dateOnly(d)+'T'+time+':00';}
function localDate(daysOffset=0){const d=new Date();d.setDate(d.getDate()+daysOffset);return dateOnly(d);}

function defaultState(){
  const p1 = makeDemoPackage({id:'PKG-2026-00001',productType:'Meat',productName:'Chicken Breast',batch:'CHK-001',offset:0,time:'10:30',stage:'Fresh',temp:4.2});
  const p2 = makeDemoPackage({id:'PKG-2026-00002',productType:'Dairy',productName:'Milk',batch:'MLK-001',offset:-1,time:'09:15',stage:'Early Spoilage',temp:5.8});
  const p3 = makeDemoPackage({id:'PKG-2026-00003',productType:'Ready-to-Eat',productName:'Ready-to-Eat Meal',batch:'RTE-001',offset:-2,time:'17:40',stage:'Moderate Spoilage',temp:7.2});
  const p4 = makeDemoPackage({id:'PKG-2026-00004',productType:'Bakery',productName:'Bread',batch:'BRD-001',offset:-3,time:'08:45',stage:'High Indication',temp:25});
  return {company:{name:'ABC Foods Pvt Ltd',location:'Chennai, Tamil Nadu',contact:'Demo User',email:'demo@freshtrace.bio'},profile:{name:'Dhasi',role:'Manufacturer'},packages:{[p1.packageId]:p1,[p2.packageId]:p2,[p3.packageId]:p3,[p4.packageId]:p4},settings:{demoMode:true,publicBaseUrl:DEFAULT_PUBLIC_BASE_URL},notifications:[]};
}
function makeDemoPackage({id,productType,productName,batch,offset,time,stage,temp}){
  const profile=PRODUCT_PROFILES[productType]; const packaging=demoDate(offset,time); const packagingDate=packaging.slice(0,10); const expiry=addDays(packagingDate,profile.shelfDays); const vals=getStageValues(productType,stage,temp); const history=[];
  const stageTrail = stage==='Fresh'?['Fresh']:stage==='Early Spoilage'?['Fresh','Early Spoilage']:stage==='Moderate Spoilage'?['Fresh','Early Spoilage','Moderate Spoilage']:['Fresh','Early Spoilage','Moderate Spoilage','High Indication'];
  stageTrail.forEach((s,i)=>{ const ts = new Date(packaging); ts.setHours(ts.getHours()+Math.max(2,i*12)); const vv=getStageValues(productType,s,i===stageTrail.length-1?temp:profile.idealTemp); history.push({timestamp:ts.toISOString(),temperature:vv.temperature,gasIndex:vv.gas,pH:vv.pH,stickerColor:COLOR_FOR_STAGE[s],freshnessScore:vv.freshness,spoilageIndex:100-vv.freshness,status:s,condition:vv.condition,contaminationLevel:vv.contamination}); });
  return {packageId:id,companyId:'company-1',companyName:'ABC Foods Pvt Ltd',companyLocation:'Chennai, Tamil Nadu',productType,productName,batchNumber:batch,manufacturingDate:packagingDate,packagingDate,packagingTime:time,storageTemperature:profile.idealTemp,expiryDate:expiry,expectedExpiryDate:expiry,description:`Demo ${productType.toLowerCase()} freshness monitoring package.`,imageData:'',monitoringStage:stage,currentTemperature:vals.temperature,currentGasValue:vals.gas,currentPH:vals.pH,currentStickerColor:COLOR_FOR_STAGE[stage],currentRGB:vals.rgb,freshnessScore:vals.freshness,spoilageIndex:100-vals.freshness,status:stage,condition:vals.condition,contaminationLevel:vals.contamination,sensorHistory:history,scans:[],updatedAt:nowISO(),createdAt:packaging};
}
function getStageValues(productType,stage,tempOverride){const prof=PRODUCT_PROFILES[productType]||PRODUCT_PROFILES.Meat;const short=STAGE_SHORT[stage]||'Fresh';const pH=prof.pH[short];const gas=prof.gas[short];const temperature=Number((tempOverride??prof.idealTemp).toFixed(1));const freshness={Fresh:96,'Early Spoilage':70,'Moderate Spoilage':44,'High Indication':16}[stage]??96;const rgb={Purple:{r:152,g:67,b:229},Yellow:{r:234,g:191,b:56},Green:{r:72,g:199,b:135},Red:{r:228,g:84,b:109}}[COLOR_FOR_STAGE[stage]];const condition=prof.condition[short];const contamination=prof.contamination[short];return {pH,gas,temperature,freshness,rgb,condition,contamination};}
function analyzePackage(pkg,forcedStage=null){
  const prof=PRODUCT_PROFILES[pkg.productType]||PRODUCT_PROFILES.Meat; const expiry=pkg.expectedExpiryDate||pkg.expiryDate||addDays(pkg.packagingDate,prof.shelfDays); pkg.expectedExpiryDate=expiry; pkg.expiryDate=expiry;
  let stage=forcedStage||pkg.monitoringStage||'Auto';
  if(stage==='Auto'){
    const ageRatio=daysBetween(`${pkg.packagingDate}T${pkg.packagingTime||'12:00'}:00`,new Date())/prof.shelfDays;
    const temp=Number(pkg.currentTemperature||pkg.storageTemperature||prof.idealTemp);
    const tempPenalty=temp>prof.idealTemp+2 ? 0.12 : temp>prof.idealTemp+1 ? 0.06 : 0;
    const adjusted=ageRatio+tempPenalty;
    if(adjusted<=0.45)stage='Fresh'; else if(adjusted<=0.82)stage='Early Spoilage'; else if(adjusted<=1.05)stage='Moderate Spoilage'; else stage='High Indication';
  }
  const vals=getStageValues(pkg.productType,stage,pkg.currentTemperature||prof.idealTemp); pkg.monitoringStage=stage; pkg.currentPH=vals.pH; pkg.currentGasValue=vals.gas; pkg.currentTemperature=vals.temperature; pkg.currentStickerColor=COLOR_FOR_STAGE[stage]; pkg.currentRGB=vals.rgb; pkg.freshnessScore=vals.freshness; pkg.spoilageIndex=100-vals.freshness; pkg.status=stage; pkg.condition=vals.condition; pkg.contaminationLevel=vals.contamination; pkg.updatedAt=nowISO(); return pkg;
}
function loadState(){try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)return JSON.parse(raw);const s=defaultState();localStorage.setItem(STORAGE_KEY,JSON.stringify(s));return s;}catch(e){return defaultState();}}
function saveState(s){localStorage.setItem(STORAGE_KEY,JSON.stringify(s));state=s;}
let state=loadState();

function routeFromHash(){const raw=(location.hash||'#home').slice(1);const [route,...rest]=raw.split('/');const id=rest.join('/');return {route:route||'home',id:id?decodeURIComponent(id.split('?')[0]):null};}
function navigate(route,id=''){location.hash=id?`${route}/${encodeURIComponent(id)}`:route;}
function buildScanUrl(packageId){const base=(state.settings.publicBaseUrl||window.location.origin+window.location.pathname).replace(/#.*$/,'').replace(/\/$/,''); const p=state.packages[packageId]; if(!p)return `${base}#scan/${encodeURIComponent(packageId)}`; const q=new URLSearchParams({packageId:p.packageId,batch:p.batchNumber,product:p.productName,company:p.companyName,productType:p.productType}); return `${base}#scan/${encodeURIComponent(packageId)}?${q.toString()}`;}
function qrImagePaths(packageId){return [`${packageId}.png`,`qr-codes/${packageId}.png`,`images/qr-codes/${packageId}.png`,`assets/qr/${packageId}.png`];}
function qrImgMarkup(p, className='qr-static-img', alt='Package QR'){const paths=qrImagePaths(p.packageId);return `<img class="${className}" src="${paths[0]}" data-qr-paths="${esc(JSON.stringify(paths))}" alt="${esc(alt)}" loading="lazy" style="width:224px!important;height:224px!important;max-width:100%!important;max-height:100%!important;object-fit:contain;display:block;"/>`;}
function wireStaticQr(root, p, fallbackId){const img=root?.querySelector?.(`[data-qr-paths]`);if(!img||!p)return;let paths=[];try{paths=JSON.parse(img.getAttribute('data-qr-paths')||'[]');}catch{};let i=0;img.onerror=()=>{if(i<paths.length-1){i+=1;img.src=paths[i];}else{img.style.display='none';const fb=document.getElementById(fallbackId);if(fb&&window.QRCode){fb.style.display='block';fb.innerHTML='';new QRCode(fb,{text:buildScanUrl(p.packageId),width:224,height:224,colorDark:'#15111e',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.H});}}};}

function statusClass(stage){return ({Fresh:'badge-purple','Early Spoilage':'badge-yellow','Moderate Spoilage':'badge-green','High Indication':'badge-red'})[stage]||'badge-neutral';}
function showToast(message,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=message;document.getElementById('toast-root').appendChild(el);setTimeout(()=>el.remove(),3200);}
function layout(title,subtitle,body,actions=''){return `<div class="container"><div class="page-header"><div><div class="eyebrow">FreshTrace Bio</div><h1>${esc(title)}</h1><p>${esc(subtitle||'')}</p></div><div class="btn-row">${actions}</div></div>${body}<div class="footer-note">FreshTrace Bio · Smart food freshness monitoring · Demo calibration values are for interface demonstration</div></div>`;}

