function initHome(){
  clearInterval(homeTimer);
  const apply=()=>{
    const s=HOME_STATES[window.__freshHomeIndex%HOME_STATES.length];
    const core=document.getElementById('home-bio-core');
    if(!core)return;
    core.className=`bio-core ${s.color.toLowerCase()}`;
    document.getElementById('home-color').textContent=`Color: ${s.color}`;
    document.getElementById('home-ph').textContent=s.pH;
    document.getElementById('home-temp').textContent=`${s.temp}°C`;
    document.getElementById('home-freshness').textContent=`${s.freshness}%`;
    document.getElementById('home-condition').textContent=s.condition;
    document.getElementById('home-stage').textContent=s.stage;
    document.getElementById('home-shelf').textContent=s.shelf==='0h'?'Monitor now':`${s.shelf} remaining`;
    window.__freshHomeIndex=(window.__freshHomeIndex+1)%HOME_STATES.length;
  };
  if(typeof window.__freshHomeIndex!=='number')window.__freshHomeIndex=0;
  apply();
  homeTimer=setInterval(apply,2500);
  const p=state.packages['PKG-2026-00001']||Object.values(state.packages)[0];
  const target=document.getElementById('home-qr');
  if(target&&p){target.innerHTML=qrImgMarkup(p,'home-qr-image',`QR for ${p.productName}`)+`<div id="home-qr-fallback" style="display:none"></div>`;wireStaticQr(target,p,'home-qr-fallback');}
}

function renderDashboard(){
  const ps=Object.values(state.packages);const counts={total:ps.length,fresh:ps.filter(p=>p.status==='Fresh').length,early:ps.filter(p=>p.status==='Early Spoilage').length,moderate:ps.filter(p=>p.status==='Moderate Spoilage').length,high:ps.filter(p=>p.status==='High Indication').length};const avg=ps.length?Math.round(ps.reduce((s,p)=>s+p.freshnessScore,0)/ps.length):0;const ph=ps.length?(ps.reduce((s,p)=>s+p.currentPH,0)/ps.length).toFixed(1):'—';const temp=ps.length?(ps.reduce((s,p)=>s+p.currentTemperature,0)/ps.length).toFixed(1):'—';
  const body=`<div class="card portfolio-banner"><div><div class="eyebrow">Manufacturer Dashboard</div><h2>Overview of your package monitoring portfolio</h2><p>Live view of freshness, pH, temperature, condition and QR-linked package status.</p></div><button class="btn btn-primary" data-route="register">＋ Register Package</button></div><div class="dashboard-grid">${[['Total Packages',counts.total,'▦','Live package portfolio'],['Fresh 🟣',counts.fresh,'●','Fresh condition'],['Early Spoilage 🟡',counts.early,'●','Early indication'],['Moderate Spoilage 🟢',counts.moderate,'●','Moderate indication'],['High Indication 🔴',counts.high,'●','High indication'],['Average Freshness',`${avg}/100`,'◌','Portfolio average']].map(x=>`<div class="card stat-card enhanced"><div class="stat-top"><span>${x[0]}</span><b>${x[2]}</b></div><div class="stat-value">${x[1]}</div><div class="stat-note">${x[3]}</div></div>`).join('')}</div><div class="grid grid-4 insight-grid"><div class="insight-card"><small>AVERAGE PH</small><strong>${ph}</strong><span>Across active package readings</span></div><div class="insight-card"><small>AVG TEMPERATURE</small><strong>${temp}°C</strong><span>Current package readings</span></div><div class="insight-card"><small>AVERAGE GAS</small><strong>${ps.length?(ps.reduce((s,p)=>s+Number(p.currentGasValue||0),0)/ps.length).toFixed(0):'—'}</strong><span>Gas sensor index</span></div><div class="insight-card"><small>QR SCAN READY</small><strong>${ps.length}</strong><span>Product-specific QR identities</span></div></div><div class="grid grid-4 insight-grid" style="margin-top:12px"><div class="insight-card"><small>EARLIEST EXPIRY</small><strong>${ps.length?fmtDate(ps.slice().sort((a,b)=>new Date(a.expectedExpiryDate)-new Date(b.expectedExpiryDate))[0].expectedExpiryDate):'—'}</strong><span>Nearest expected expiry</span></div><div class="insight-card"><small>AT-RISK PACKAGES</small><strong>${counts.moderate+counts.high}</strong><span>Moderate + high indication</span></div><div class="insight-card"><small>PORTFOLIO CONDITION</small><strong>${avg>=80?'Stable':avg>=55?'Watch':'At Risk'}</strong><span>Prototype freshness index</span></div><div class="insight-card"><small>COMPANY</small><strong>${esc(state.company.name)}</strong><span>${esc(state.company.location)}</span></div></div><div class="card" style="margin-top:18px"><div class="card-head"><div><h3>Live package portfolio</h3><span class="muted">pH · temperature · condition · sticker · expected expiry</span></div><button class="btn btn-secondary" data-route="packages">View all</button></div><div class="table-wrap"><table class="data-table enhanced-table"><thead><tr><th>Package</th><th>Product</th><th>Batch</th><th>pH</th><th>Temp</th><th>Gas</th><th>Food Condition</th><th>Sticker</th><th>Expected Expiry</th><th>QR</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><span class="mono">${esc(p.packageId)}</span></td><td><strong>${esc(p.productName)}</strong><div class="muted">${esc(p.productType)}</div></td><td>${esc(p.batchNumber)}</td><td>${p.currentPH}</td><td>${p.currentTemperature}°C</td><td>${p.currentGasValue}</td><td><span class="badge ${statusClass(p.status)}">${esc(p.condition)}</span></td><td><span class="sticker-pill ${statusClass(p.status)}">${stageInfo(p.status).symbol} ${esc(p.currentStickerColor)}</span></td><td>${fmtDate(p.expectedExpiryDate)}</td><td><span class="qr-ready">QR READY</span></td><td><button class="btn btn-ghost" onclick="navigate('packages','${p.packageId}')">Open</button></td></tr>`).join('')}</tbody></table></div></div>`;
  return layout('Manufacturer Dashboard','Overview of your package monitoring portfolio.',body);
}

function renderRegister(){
  return layout('Register Food Package','Create the package identity, automatically calculate expected expiry and generate its freshness model.',`<div class="register-layout"><div class="card pad"><div class="stepper"><div class="step active"><span>1</span> Product</div><div class="step-line"></div><div class="step active"><span>2</span> Packaging</div><div class="step-line"></div><div class="step active"><span>3</span> Image</div><div class="step-line"></div><div class="step active"><span>4</span> Analyze</div></div><form id="package-form" class="form-grid"><div class="field full"><label>Product Type</label><select name="productType" id="product-type"><option>Meat</option><option>Dairy</option><option>Ready-to-Eat</option><option>Bakery</option></select><small class="field-hint">Each category uses its own recommended shelf-life profile.</small></div><div class="field"><label>Product Name *</label><input name="productName" required placeholder="e.g. Chicken Breast"/></div><div class="field"><label>Batch Number *</label><input name="batchNumber" required placeholder="e.g. CHK-001"/></div><div class="field"><label>Manufacturing Date *</label><input type="date" name="manufacturingDate" value="${localDate()}" required/></div><div class="field"><label>Packaging Date *</label><input type="date" name="packagingDate" id="packaging-date" value="${localDate()}" required/></div><div class="field"><label>Packaging Time *</label><input type="time" name="packagingTime" value="10:30" required/></div><div class="field"><label>Storage Temperature (°C)</label><input type="number" step="0.1" name="storageTemperature" id="storage-temp" value="4"/></div><div class="field"><label>Expected Expiry Date</label><input type="date" name="expiryDate" id="expiry-date" readonly/></div><div class="field full"><label>Demo Analysis Stage <span class="mini-tag">Optional</span></label><select name="demoStage"><option value="Auto">Auto — analyze from package age + temperature</option><option value="Fresh">Fresh — Purple</option><option value="Early Spoilage">Early Spoilage — Yellow</option><option value="Moderate Spoilage">Moderate Spoilage — Green</option><option value="High Indication">High Indication — Red</option></select><small class="field-hint">Use this for your Innovators Day demo. The selected stage drives the demo colour, pH, temperature, condition and freshness report; real deployments should use calibrated sensor data.</small></div><div class="field full"><label>Product Description</label><textarea name="description" placeholder="Short package or experiment description"></textarea></div><div class="field full"><button class="btn btn-primary" type="submit">Create Package & Analyze →</button></div></form></div><div class="card pad sticky-panel"><div class="eyebrow">Automatic profile</div><h3 id="profile-name">Meat · 3 day recommended window</h3><p class="muted" id="profile-note">Demo calibration profile for package analysis.</p><div class="profile-preview"><div><span>Fresh pH</span><strong id="profile-ph">5.8</strong></div><div><span>Ideal temp</span><strong id="profile-temp">4°C</strong></div><div><span>Expected expiry</span><strong id="profile-expiry">—</strong></div></div><div class="upload" style="margin-top:16px"><strong>Upload product image</strong><small>JPG, PNG, WEBP · shown on QR freshness report</small><input id="product-image" type="file" accept="image/*"/></div><img id="product-preview" class="preview-img" alt="Product preview" style="display:none"/><div class="notice" style="margin-top:16px">After registration, the system calculates <strong>pH, temperature, sticker colour, food condition, spoilage indication and expected expiry</strong> for the package.</div></div></div>`);
}
function initRegister(){
  const type=document.getElementById('product-type'),date=document.getElementById('packaging-date'),temp=document.getElementById('storage-temp'),expiry=document.getElementById('expiry-date');const update=()=>{const p=PRODUCT_PROFILES[type.value];document.getElementById('profile-name').textContent=`${type.value} · ${p.shelfDays} day recommended window`;document.getElementById('profile-ph').textContent=p.pH.Fresh;document.getElementById('profile-temp').textContent=`${p.idealTemp}°C`;const ed=addDays(date.value||localDate(),p.shelfDays);expiry.value=ed;document.getElementById('profile-expiry').textContent=fmtDate(ed);if(!temp.dataset.manual)temp.value=p.idealTemp;};type.addEventListener('change',update);date.addEventListener('change',update);temp.addEventListener('input',()=>temp.dataset.manual='true');update();
  document.getElementById('product-image').addEventListener('change',()=>{const f=document.getElementById('product-image').files?.[0];if(f){const pre=document.getElementById('product-preview');pre.src=URL.createObjectURL(f);pre.style.display='block';}});
  document.getElementById('package-form').addEventListener('submit',async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);const productType=fd.get('productType');const number=Object.keys(state.packages).length+1;const packageId=`PKG-2026-${String(number).padStart(5,'0')}`;let imageData='';const f=document.getElementById('product-image').files?.[0];if(f)imageData=await fileToDataURL(f);const prof=PRODUCT_PROFILES[productType];let pkg={packageId,companyId:'company-1',companyName:state.company.name,companyLocation:state.company.location,productType,productName:fd.get('productName'),batchNumber:fd.get('batchNumber'),manufacturingDate:fd.get('manufacturingDate'),packagingDate:fd.get('packagingDate'),packagingTime:fd.get('packagingTime'),storageTemperature:Number(fd.get('storageTemperature')||prof.idealTemp),expiryDate:fd.get('expiryDate'),expectedExpiryDate:fd.get('expiryDate'),description:fd.get('description'),imageData,monitoringStage:fd.get('demoStage'),currentTemperature:Number(fd.get('storageTemperature')||prof.idealTemp),currentGasValue:prof.gas.Fresh,currentPH:prof.pH.Fresh,currentStickerColor:'Purple',currentRGB:{r:152,g:67,b:229},freshnessScore:96,spoilageIndex:4,status:'Fresh',condition:prof.condition.Fresh,contaminationLevel:prof.contamination.Fresh,sensorHistory:[],scans:[],createdAt:dateTimeLocalISO(fd.get('packagingDate'),fd.get('packagingTime')),updatedAt:nowISO()};analyzePackage(pkg,fd.get('demoStage')==='Auto'?null:fd.get('demoStage'));pkg.sensorHistory.push({timestamp:pkg.updatedAt,temperature:pkg.currentTemperature,gasIndex:pkg.currentGasValue,pH:pkg.currentPH,stickerColor:pkg.currentStickerColor,freshnessScore:pkg.freshnessScore,spoilageIndex:pkg.spoilageIndex,status:pkg.status,condition:pkg.condition,contaminationLevel:pkg.contaminationLevel});state.packages[packageId]=pkg;state.notifications.unshift({id:Date.now(),message:`${pkg.productName} registered as ${pkg.status}`,time:nowISO(),type:'success'});saveState(state);showToast(`${pkg.productName} analyzed · ${pkg.currentStickerColor} · pH ${pkg.currentPH}`,'success');navigate('packages',packageId);});
}

function renderPackages(id=null){if(id){const p=state.packages[id];return p?renderPackageDetail(p):renderNotFound();}return layout('My Packages','Search package, batch, product or condition.',`<div class="card pad"><div class="searchbar"><input id="pkg-search" placeholder="Search product, batch or package ID"/><select id="pkg-filter" class="filter"><option value="all">All statuses</option>${STAGES.map(s=>`<option>${s}</option>`).join('')}</select></div></div><div class="card" style="margin-top:16px"><div class="table-wrap"><table class="data-table enhanced-table"><thead><tr><th>Package</th><th>Product</th><th>Batch</th><th>pH</th><th>Temp</th><th>Condition</th><th>Sticker</th><th>Expected Expiry</th><th>Status</th><th></th></tr></thead><tbody id="package-table-body"></tbody></table></div></div>`,'<button class="btn btn-primary" data-route="register">＋ Register Package</button>');}
function renderPackageRows(){const body=document.getElementById('package-table-body');if(!body)return;const q=(document.getElementById('pkg-search')?.value||'').toLowerCase(),f=document.getElementById('pkg-filter')?.value||'all';const rows=Object.values(state.packages).filter(p=>(!q||[p.packageId,p.productName,p.batchNumber,p.productType].some(v=>String(v).toLowerCase().includes(q)))&&(f==='all'||p.status===f));body.innerHTML=rows.map(p=>`<tr><td><strong class="mono">${esc(p.packageId)}</strong></td><td>${esc(p.productName)}<div class="muted">${esc(p.productType)}</div></td><td>${esc(p.batchNumber)}</td><td>${p.currentPH}</td><td>${p.currentTemperature}°C</td><td>${esc(p.condition)}</td><td>${stageInfo(p.status).symbol} ${p.currentStickerColor}</td><td>${fmtDate(p.expectedExpiryDate)}</td><td><span class="badge ${statusClass(p.status)}">${esc(p.status)}</span></td><td><button class="btn btn-ghost" onclick="navigate('packages','${p.packageId}')">Open</button></td></tr>`).join('')||`<tr><td colspan="10"><div class="placeholder"><div><strong>No packages found</strong><span>Try another search.</span></div></div></td></tr>`;}
function initPackages(){document.getElementById('pkg-search')?.addEventListener('input',renderPackageRows);document.getElementById('pkg-filter')?.addEventListener('change',renderPackageRows);renderPackageRows();}

function renderFreshCard(p){const s=stageInfo(p.status);return `<div class="fresh-card modern" style="--status-color:${s.color};--status-bg:${s.bg}"><div class="fresh-card-top"><div class="status-main"><span class="status-swatch" style="background:${s.color}"></span><div><div class="status-label">Current food condition</div><div class="status-title">${s.label}</div><div class="status-sub">${esc(p.condition)}</div></div></div><div class="score-wrap"><div class="score-label">Freshness Score</div><div class="score">${p.freshnessScore}<span>/100</span></div></div></div><div class="progress"><span style="width:${p.freshnessScore}%;background:${s.color}"></span></div><div class="kpi-row" style="margin-top:16px"><div class="kpi">pH<strong>${p.currentPH}</strong></div><div class="kpi">Temperature<strong>${p.currentTemperature}°C</strong></div><div class="kpi">Spoilage indication<strong>${esc(p.contaminationLevel)}</strong></div><div class="kpi">Expected expiry<strong>${fmtDate(p.expectedExpiryDate)}</strong></div></div></div>`;}
function sensorCard(title,value,meta,icon,color='var(--purple)'){return `<div class="card sensor-card modern"><div class="sensor-head"><div class="icon-round" style="color:${color};background:${color}18">${icon}</div><span class="live-mini">LIVE</span></div><h4>${esc(title)}</h4><div class="sensor-value">${esc(value)}</div><div class="sensor-meta">${esc(meta)}</div></div>`;}
function renderTimeline(hist){if(!hist?.length)return `<div class="placeholder"><div><strong>No monitoring readings</strong><span>Connect sensors or use demo simulation.</span></div></div>`;return `<div class="timeline">${[...hist].reverse().map((h,i)=>{const s=stageInfo(h.status);return `<div class="timeline-item ${i===0?'current':''}"><div class="timeline-dot" style="border-color:${i===0?s.color:'#7A8190'}"></div><div class="timeline-content"><div class="timeline-time">${fmtDateTime(h.timestamp)}</div><div class="timeline-title"><span class="badge ${statusClass(h.status)}">${h.stickerColor}</span> ${h.status}</div><div class="timeline-note">pH ${h.pH} · ${h.temperature}°C · Gas ${h.gasIndex} · Freshness ${h.freshnessScore}/100</div></div></div>`}).join('')}</div>`;}
function renderPackageDetail(p){
  const s=stageInfo(p.status);
  const qrUrl=buildScanUrl(p.packageId);
  return layout('Package Details',`${p.productName} · ${p.batchNumber} · ${p.packageId}`,`
    <div class="product-hero">
      <img class="product-image" src="${p.imageData||placeholderData(p.productName)}" alt="${esc(p.productName)}"/>
      <div class="card pad product-copy">
        <div class="eyebrow">${esc(p.productType)}</div>
        <h1>${esc(p.productName)}</h1>
        <p class="muted" style="margin-top:8px">${esc(p.description||'Smart monitored food package.')}</p>
        <div class="meta-row">
          <span class="meta-pill">Batch ${esc(p.batchNumber)}</span>
          <span class="meta-pill">Company ${esc(p.companyName)}</span>
          <span class="meta-pill">Package ${esc(p.packageId)}</span>
        </div>
        <div class="btn-row" style="margin-top:18px">
          <button class="btn btn-primary" data-route="qr">Open QR Generator</button>
          <button class="btn btn-secondary" onclick="openReport(${JSON.stringify(p.packageId)})">Download Report</button>
          <button class="btn btn-secondary" data-route="scan">Test Scanner</button>
        </div>
      </div>
    </div>
    ${renderFreshCard(p)}
    <div class="grid grid-4" style="margin-top:16px">
      ${sensorCard('pH Level',p.currentPH,'Current indicator pH','pH','#9B43E5')}
      ${sensorCard('Temperature',`${p.currentTemperature}°C`,'Current package temperature','℃','#3B9C9C')}
      ${sensorCard('Gas Response',p.currentGasValue,'Gas Sensor Index','NH₃','#E6BE38')}
      ${sensorCard('Sticker Colour',p.currentStickerColor,`RGB ${p.currentRGB.r}/${p.currentRGB.g}/${p.currentRGB.b}`,'●',s.color)}
    </div>
    <div class="grid grid-2" style="margin-top:16px">
      <div class="card pad">
        <h3>Product & package intelligence</h3>
        <div class="info-grid" style="margin-top:10px">
          ${infoItem('Product Type',p.productType)}
          ${infoItem('Batch Number',p.batchNumber)}
          ${infoItem('Company',p.companyName)}
          ${infoItem('Location',p.companyLocation)}
          ${infoItem('Manufacturing Date',fmtDate(p.manufacturingDate))}
          ${infoItem('Packaging Date',fmtDate(p.packagingDate))}
          ${infoItem('Packaging Time',p.packagingTime)}
          ${infoItem('Storage Temperature',`${p.storageTemperature} °C`)}
          ${infoItem('Expected Expiry',fmtDate(p.expectedExpiryDate))}
          ${infoItem('Food Condition',p.condition)}
          ${infoItem('Contamination / Spoilage indication',p.contaminationLevel)}
          ${infoItem('Package ID',p.packageId)}
        </div>
      </div>
      <div class="card pad qr-inline-card">
        <div class="section-title"><div><h3>Direct freshness report</h3><p>This package has a unique QR containing package + batch + company metadata.</p></div><span class="qr-ready">QR READY</span></div>
        <div class="detail-qr-row"><div id="detail-qr" class="detail-qr">${qrImgMarkup(p,'detail-qr-image',`QR for ${p.productName}`)}<div id="detail-qr-fallback" style="display:none"></div></div><div><div class="notice" style="word-break:break-all;margin-top:0"><strong>Direct report URL</strong><br/>${esc(qrUrl)}</div><div class="btn-row" style="margin-top:12px">
        <button class="btn btn-primary" onclick='copyText(${JSON.stringify(qrUrl)})'>Copy QR Link</button>
          <button class="btn btn-secondary" onclick='window.open(${JSON.stringify(qrUrl)},"_blank")'>Open Public Report</button>
        </div></div></div>
      </div>
    </div>
    <div class="card pad" style="margin-top:16px">
      <div class="section-title">
        <div><h2 style="font-size:20px">Monitoring timeline</h2><p>pH, temperature, gas, colour and freshness history.</p></div>
        <button class="btn btn-secondary" onclick="simulateSensor(${JSON.stringify(p.packageId)})">Simulate New Reading</button>
      </div>
      ${renderTimeline(p.sensorHistory)}
    </div>
    <div class="grid grid-2" style="margin-top:16px">
      <div class="card pad"><h3>Temperature trend</h3><div id="detail-temp-chart" class="chart-box"></div></div>
      <div class="card pad"><h3>pH trend</h3><div id="detail-ph-chart" class="chart-box"></div></div>
    </div>`);
}
function infoItem(l,v){return `<div class="info-item"><span>${esc(l)}</span><strong>${esc(v)}</strong></div>`;}
function placeholderData(label){const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="700" height="500"><defs><linearGradient id="g" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#22102f"/><stop offset="1" stop-color="#472267"/></linearGradient></defs><rect width="100%" height="100%" rx="36" fill="url(#g)"/><circle cx="350" cy="210" r="80" fill="#9B43E5" opacity=".7"/><text x="350" y="355" text-anchor="middle" font-family="Arial" font-size="36" fill="#fff">${esc(label).slice(0,24)}</text></svg>`;return 'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(svg);}

function qrMeta(p){return {packageId:p.packageId,batch:p.batchNumber,company:p.companyName,product:p.productName,report:buildScanUrl(p.packageId)};}
function renderQR(){const first=Object.keys(state.packages)[0];return layout('QR Generator','Create a product-specific QR that links one exact package, batch, company and live freshness report.',`<div class="qr-layout"><div class="card qr-panel"><div class="eyebrow">Product + Batch + Company QR</div><h2 id="qr-product-title" style="margin-top:8px"></h2><p id="qr-product-sub" class="muted" style="font-size:12px"></p><div class="qr-box" style="margin-top:16px"><div id="qr-target" class="qr-target"></div><div class="scan-caption">Scan with any smartphone camera to open the freshness report</div></div><div class="btn-row" style="justify-content:center;margin-top:16px"><button class="btn btn-primary" id="download-qr">Download QR</button><button class="btn btn-secondary" id="print-qr">Print QR</button><button class="btn btn-secondary" id="copy-qr">Copy Report Link</button></div></div><div class="card pad"><div class="section-title"><div><h2 style="font-size:20px">QR-linked package data</h2><p>The QR identity is generated from the selected package.</p></div></div><select id="qr-package-select" class="filter" style="width:100%">${Object.values(state.packages).map(p=>`<option value="${p.packageId}" ${p.packageId===first?'selected':''}>${esc(p.packageId)} · ${esc(p.productName)} · ${esc(p.batchNumber)}</option>`).join('')}</select><div id="qr-details" style="margin-top:16px"></div><div class="notice" style="margin-top:16px"><strong>Direct mobile report:</strong><br/>Scan the printed QR with the normal camera app. Tap the detected link and the exact product report opens.</div><div style="margin-top:18px"><h3>Printable package label</h3><div id="label-preview" style="margin-top:12px"></div></div></div></div>`);}
function initQR(){const sel=document.getElementById('qr-package-select');if(!sel)return;const draw=()=>{const p=state.packages[sel.value];document.getElementById('qr-product-title').textContent=p.productName;document.getElementById('qr-product-sub').textContent=`${p.productType} · Batch ${p.batchNumber} · ${p.companyName}`;const target=document.getElementById('qr-target');target.innerHTML=qrImgMarkup(p,'qr-main-image',`Product QR for ${p.productName}`)+`<div id="qr-main-fallback" style="display:none"></div>`;wireStaticQr(target,p,'qr-main-fallback');const url=buildScanUrl(p.packageId);const m=qrMeta(p);document.getElementById('qr-details').innerHTML=`<div class="qr-data-grid"><div class="qr-data-item"><span>Package ID</span><strong>${esc(m.packageId)}</strong></div><div class="qr-data-item"><span>Batch Number</span><strong>${esc(m.batch)}</strong></div><div class="qr-data-item"><span>Company</span><strong>${esc(m.company)}</strong></div><div class="qr-data-item"><span>Product</span><strong>${esc(m.product)}</strong></div></div><div class="notice" style="margin-top:12px;word-break:break-all"><strong>Direct freshness report URL</strong><br/>${esc(m.report)}</div>`;const lp=document.getElementById('label-preview');lp.innerHTML=`<div class="label-preview"><div class="label-brand">FRESHTRACE BIO</div><div class="label-subtitle">SMART FOOD FRESHNESS REPORT</div><div id="label-qr" class="label-qr">${qrImgMarkup(p,'label-qr-image',`Printable QR for ${p.productName}`)}</div><div id="label-qr-fallback" style="display:none"></div><div class="label-meta"><strong>${esc(p.productName)}</strong><span>Batch: ${esc(p.batchNumber)}</span><span>Company: ${esc(p.companyName)}</span><span>Package: ${esc(p.packageId)}</span></div></div>`;wireStaticQr(lp,p,'label-qr-fallback');document.getElementById('download-qr').onclick=()=>downloadQrStatic(p);document.getElementById('print-qr').onclick=()=>printLabel(p);document.getElementById('copy-qr').onclick=()=>copyText(url);};sel.addEventListener('change',draw);draw();}
function downloadQrStatic(p){const paths=qrImagePaths(p.packageId);let i=0;const a=document.createElement('a');a.download=`${p.packageId}-${p.batchNumber}-QR.png`;const test=new Image();test.onload=()=>{a.href=paths[i];a.click();};test.onerror=()=>{i++;if(i<paths.length)test.src=paths[i];else{const div=document.createElement('div');div.style.position='fixed';div.style.left='-99999px';document.body.appendChild(div);new QRCode(div,{text:buildScanUrl(p.packageId),width:400,height:400,colorDark:'#15111e',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.H});setTimeout(()=>{const c=div.querySelector('canvas');if(c){a.href=c.toDataURL('image/png');a.click();}div.remove();},80);}};test.src=paths[i];}
function downloadQr(target,p){const c=target.querySelector('canvas');if(!c)return;const a=document.createElement('a');a.href=c.toDataURL('image/png');a.download=`${p.packageId}-${p.batchNumber}-QR.png`;a.click();}
function printLabel(p){const url=buildScanUrl(p.packageId);const w=window.open('','_blank');w.document.write(`<html><head><title>${esc(p.packageId)} QR</title><style>body{font-family:Arial;display:grid;place-items:center;min-height:100vh}.label{width:340px;border:2px solid #17111f;border-radius:18px;padding:20px;text-align:center}.brand{font-weight:900;letter-spacing:.18em;color:#4B2A68}.sub{font-size:9px;color:#777;letter-spacing:.12em;margin:7px 0}.meta{font-size:11px;line-height:1.7;color:#444}</style></head><body><div class="label"><div class="brand">FRESHTRACE BIO</div><div class="sub">SMART FOOD FRESHNESS REPORT</div><div id="qr"></div><div class="meta"><strong>${esc(p.productName)}</strong><br/>Batch: ${esc(p.batchNumber)}<br/>Company: ${esc(p.companyName)}<br/>Package: ${esc(p.packageId)}</div></div><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"><\/script><script>new QRCode(document.getElementById('qr'),{text:${JSON.stringify(url)},width:180,height:180});window.print();<\/script></body></html>`);w.document.close();}

function renderPublic(p){const s=stageInfo(p.status);return `<div class="public-shell"><div class="public-header"><div class="brand small-brand"><span class="brand-mark">FB</span><span><strong>FreshTrace</strong><small>Bio</small></span></div><div class="verified"><span class="verified-dot">✓</span>Package verified</div></div><div class="public-product"><img class="public-image" src="${p.imageData||placeholderData(p.productName)}" alt="${esc(p.productName)}"/><div><div class="eyebrow">${esc(p.productType)} · ${esc(p.batchNumber)}</div><h1>${esc(p.productName)}</h1><p class="muted">${esc(p.companyName)} · ${esc(p.companyLocation)}</p><div class="meta-row"><span class="meta-pill">Package ${esc(p.packageId)}</span><span class="meta-pill">Batch ${esc(p.batchNumber)}</span><span class="meta-pill">Expected expiry ${fmtDate(p.expectedExpiryDate)}</span></div></div><div id="public-qr" class="public-qr">${qrImgMarkup(p,'public-qr-image',`QR for ${p.productName}`)}<div id="public-qr-fallback" style="display:none"></div></div></div><div class="public-fresh" style="--pcolor:${s.color};--pbg:${s.bg}"><div><div class="status-label">LIVE FOOD CONDITION</div><div class="public-status">${s.symbol} ${esc(s.label)}</div><div class="status-sub">${esc(p.condition)}</div></div><div class="score-wrap"><div class="score-label">Freshness Score</div><div class="score">${p.freshnessScore}<span>/100</span></div></div></div><div class="public-sensors"><div>${sensorCard('pH Level',p.currentPH,'Indicator pH','pH','#9B43E5')}</div><div>${sensorCard('Temperature',`${p.currentTemperature}°C`,'Current package temperature','℃','#3B9C9C')}</div><div>${sensorCard('Gas Response',p.currentGasValue,'Gas Sensor Index','NH₃','#E6BE38')}</div><div>${sensorCard('Sticker Colour',p.currentStickerColor,`RGB ${p.currentRGB.r}/${p.currentRGB.g}/${p.currentRGB.b}`,'●',s.color)}</div></div><div class="public-section-grid"><div class="card pad"><h3>Product details</h3><div class="info-grid" style="margin-top:10px">${infoItem('Product Type',p.productType)}${infoItem('Batch Number',p.batchNumber)}${infoItem('Company Name',p.companyName)}${infoItem('Company Location',p.companyLocation)}${infoItem('Manufacturing Date',fmtDate(p.manufacturingDate))}${infoItem('Packaging Date',fmtDate(p.packagingDate))}${infoItem('Packaging Time',p.packagingTime)}${infoItem('Expected Expiry',fmtDate(p.expectedExpiryDate))}${infoItem('Storage Temperature',`${p.storageTemperature} °C`)}${infoItem('Food Condition',p.condition)}${infoItem('Spoilage indication',p.contaminationLevel)}${infoItem('Estimated remaining',remainingText(p))}</div></div><div class="card pad"><h3>Smart package timeline</h3>${renderTimeline(p.sensorHistory)}</div></div><div class="grid grid-2" style="margin-top:16px"><div class="card pad"><h3>Temperature trend</h3><div id="public-temp-chart" class="chart-box"></div></div><div class="card pad"><h3>pH change trend</h3><div id="public-ph-chart" class="chart-box"></div></div></div><div class="card pad" style="margin-top:16px"><div class="section-title"><div><h3>QR identity</h3><p class="muted">This report is dynamically linked to Package ${esc(p.packageId)}. Future sensor readings can update the same page.</p></div><button class="btn btn-secondary" onclick="navigate('home')">FreshTrace Home</button></div></div></div>`;}
function remainingText(p){const expiry=new Date(`${p.expectedExpiryDate}T23:59:59`);const h=Math.round((expiry-new Date())/3600000);return h<=0?'Expired / monitor now':`${h} hours remaining`;}

function renderScan(){return layout('Scan Food QR','Use your phone camera or upload a QR image to open a package-specific freshness report.',`<div class="scan-shell"><div class="scanner-box"><div id="reader"></div></div><div class="scan-help"><strong>Normal phone camera:</strong> You can also scan the printed QR directly with your phone’s normal camera and tap the detected FreshTrace link.</div><div class="scan-actions"><button class="btn btn-primary" id="start-camera">Enable Camera</button><label class="btn btn-secondary">Upload QR Image<input id="qr-upload" type="file" accept="image/*" hidden/></label><button class="btn btn-secondary" id="manual-scan">Enter Package ID</button></div></div>`);}
let scanner=null;function initScanner(){document.getElementById('start-camera')?.addEventListener('click',async()=>{if(!window.Html5Qrcode){showToast('QR scanner library unavailable','error');return;}if(scanner)return;scanner=new Html5Qrcode('reader');try{await scanner.start({facingMode:'environment'},{fps:10,qrbox:250},txt=>{const m=txt.match(/scan\/([^/?#]+)/);if(m){scanner.stop();scanner=null;navigate('scan',decodeURIComponent(m[1]));}},()=>{});}catch(e){showToast('Camera permission is unavailable. Use Upload QR Image.','warn');}});document.getElementById('manual-scan')?.addEventListener('click',()=>{const id=prompt('Enter Package ID, e.g. PKG-2026-00001');if(id&&state.packages[id.trim()])navigate('scan',id.trim());else if(id)showToast('Package not found','error');});document.getElementById('qr-upload')?.addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f||!window.Html5Qrcode)return;const reader=new Html5Qrcode('reader');try{const txt=await reader.scanFile(f,true);const m=txt.match(/scan\/([^/?#]+)/);if(m)navigate('scan',decodeURIComponent(m[1]));else showToast('QR detected, but no FreshTrace package ID was found.','warn');}catch(err){showToast('Could not read that QR image.','error');}});}

function renderAnalytics(){return `<div class="analytical-page"><div class="analytical-head"><div><div class="analytical-eyebrow">FreshTrace Analytics</div><h1>Analytical</h1><p>Predictive freshness views inspired by the reference analytical interface: pH change, shelf-life, microbial growth and volatile-base trends.</p></div><div class="analytics-tabs"><button class="active" data-a-tab="shelf">Shelf-Life Prediction Curve</button><button data-a-tab="tvbn">TVB-N Curve</button><button data-a-tab="microbial">Microbial Growth Curve</button><button data-a-tab="ph">pH Change Trend</button></div></div><div class="analytics-main-grid"><div class="analytics-chart-card"><div class="chart-head"><div><span class="chart-kicker" id="analytics-kicker">SHELF-LIFE PREDICTION</span><h2 id="analytics-title">Shelf-Life Prediction Curve</h2><p id="analytics-subtitle">AI-style freshness projection as a visual prototype.</p></div><span class="chart-note">X axis: hours since packaging</span></div><div id="analytics-big-chart" class="big-chart"></div><div class="legend-row"><span><i class="legend-dot cyan"></i>AI prediction</span><span><i class="legend-line"></i>Lab-measured reference</span><span><i class="legend-axis"></i>X axis: hours since packaging</span></div></div><div class="analytics-side-card"><div class="chart-head"><div><span class="chart-kicker">PH CHANGE</span><h2>pH trend</h2></div></div><div id="analytics-side-chart" class="side-chart"></div><div class="micro-metrics"><div><span>Current pH</span><strong>7.3</strong></div><div><span>Temperature</span><strong>7.2°C</strong></div><div><span>Gas Index</span><strong>62</strong></div></div></div></div><div class="analytics-legend-cards"><div><span class="legend-status fresh-dot"></span><div><strong>Fresh</strong><small>pH ≤ 6.2 · low spoilage indication</small></div></div><div><span class="legend-status warn-dot"></span><div><strong>Warning</strong><small>pH 6.3–7.2 · early/moderate risk</small></div></div><div><span class="legend-status unsafe-dot"></span><div><strong>High indication</strong><small>pH > 7.2 · high spoilage indication</small></div></div></div><div class="analytics-alerts"><div class="analytic-alert danger"><span>△</span><div><strong>pH crossing threshold</strong><p>Volatile/basic signal is projected to enter the warning band.</p></div></div><div class="analytic-alert purple"><span>✣</span><div><strong>Microbial growth trend</strong><p>Growth index rises as packaging age and temperature increase.</p></div></div><div class="analytic-alert teal"><span>✣</span><div><strong>Cold-chain intervention window</strong><p>Holding chilled storage reduces the expected spoilage rate in the demo model.</p></div></div></div></div>`;}
function initAnalytics(){const data={shelf:{title:'Shelf-Life Prediction Curve',kicker:'SHELF-LIFE PREDICTION',sub:'AI-predicted freshness as measured reference',y:[100,92,82,71,58,44,29,17,8,2]},tvbn:{title:'TVB-N Curve',kicker:'VOLATILE BASIC NITROGEN',sub:'Projected TVB-N style trend for a demo meat profile',y:[8,9,11,13,15,18,21,25,28,31]},microbial:{title:'Microbial Growth Curve',kicker:'MICROBIAL GROWTH',sub:'Growth index across packaging age',y:[1.0,1.3,1.8,2.5,3.7,5.2,6.6,7.4,8.2,9.1]},ph:{title:'pH Change Trend',kicker:'PH CHANGE',sub:'Indicator pH progression through package age',y:[5.8,5.9,6.1,6.4,6.7,7.0,7.3,7.6,7.9,8.1]}};let key='shelf';const draw=()=>{const d=data[key];document.getElementById('analytics-title').textContent=d.title;document.getElementById('analytics-kicker').textContent=d.kicker;document.getElementById('analytics-subtitle').textContent=d.sub;document.getElementById('analytics-big-chart').innerHTML=polyChart(d.y,'#C95BFF','#37E0D0',true);document.getElementById('analytics-side-chart').innerHTML=polyChart(data.ph.y,'#C95BFF','#C95BFF',false);};document.querySelectorAll('[data-a-tab]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-a-tab]').forEach(b=>b.classList.remove('active'));btn.classList.add('active');key=btn.dataset.aTab;draw();}));draw();}
function polyChart(vals,stroke,areaStroke,area){const W=820,H=340,pad=34,min=Math.min(...vals),max=Math.max(...vals),range=max-min||1;const pts=vals.map((v,i)=>[pad+i*(W-pad*2)/(vals.length-1),H-pad-(v-min)/range*(H-pad*2)]);let path=`M${pts[0][0]} ${pts[0][1]} `+pts.slice(1).map(p=>`L${p[0]} ${p[1]}`).join(' ');const areaPath=`M${pts[0][0]} ${H-pad} L${pts[0][0]} ${pts[0][1]} `+pts.slice(1).map(p=>`L${p[0]} ${p[1]}`).join(' ')+`L${pts[pts.length-1][0]} ${H-pad} Z`;return `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><defs><linearGradient id="ag" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${areaStroke}" stop-opacity=".24"/><stop offset="1" stop-color="${areaStroke}" stop-opacity="0"/></linearGradient></defs>${[0.25,0.5,0.75].map(t=>`<line x1="${pad}" x2="${W-pad}" y1="${pad+(H-pad*2)*t}" y2="${pad+(H-pad*2)*t}" stroke="#332d4a"/>`).join('')}${area?`<path d="${areaPath}" fill="url(#ag)"/>`:''}<path d="${path}" fill="none" stroke="${stroke}" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${pts.map(p=>`<circle cx="${p[0]}" cy="${p[1]}" r="3" fill="${stroke}"/>`).join('')}<text x="${pad}" y="18" fill="#8b88a5" font-size="11">${max}</text><text x="${pad}" y="${H-8}" fill="#8b88a5" font-size="11">${min}</text><text x="${W-pad}" y="${H-8}" text-anchor="end" fill="#8b88a5" font-size="11">120 h</text></svg>`;}

function renderResearch(){return layout('Research Workspace','Calibration, experimental imagery and validation views for the indicator system.',`<div class="grid grid-3"><div class="card pad"><div class="eyebrow">Calibration</div><h3 style="margin-top:7px">Product profiles</h3><p class="muted">Meat · Dairy · Bakery · Ready-to-Eat</p><button class="btn btn-secondary" style="margin-top:14px" data-route="settings">Open Settings</button></div><div class="card pad"><div class="eyebrow">Indicator</div><h3 style="margin-top:7px">Colour calibration</h3><p class="muted">Purple → Yellow → Green → Red</p><div class="chip-row"><span class="chip purple-chip">Purple</span><span class="chip yellow-chip">Yellow</span><span class="chip green-chip">Green</span><span class="chip red-chip">Red</span></div></div><div class="card pad"><div class="eyebrow">Reference data</div><h3 style="margin-top:7px">Analytical models</h3><p class="muted">pH, temperature, gas and shelf-life trends.</p><button class="btn btn-secondary" style="margin-top:14px" data-route="analytics">Open Analytical</button></div></div><div class="card pad" style="margin-top:16px"><h3>Experimental note</h3><p class="muted" style="line-height:1.7">The UI uses demo calibration values for pH, temperature, gas and colour transitions. For a research submission, replace them with your measured values and validated reference data.</p></div>`);}

function renderSettings(){return layout('Settings','Company profile, public URL and demo controls.',`<div class="grid grid-2"><div class="card pad"><h3>Company profile</h3><form id="company-form" class="form-grid" style="margin-top:16px"><div class="field full"><label>Company Name</label><input name="name" value="${esc(state.company.name)}"/></div><div class="field full"><label>Location</label><input name="location" value="${esc(state.company.location)}"/></div><div class="field"><label>Contact</label><input name="contact" value="${esc(state.company.contact||'')}"/></div><div class="field"><label>Email</label><input name="email" value="${esc(state.company.email||'')}"/></div><div class="field full"><button class="btn btn-primary">Save Company</button></div></form></div><div class="card pad"><h3>Demo / public settings</h3><form id="settings-form" class="form-grid" style="margin-top:16px"><div class="field full"><label>Public Base URL</label><input name="publicBaseUrl" value="${esc(state.settings.publicBaseUrl||'')}"/></div><div class="field full"><label>Demo Mode</label><select name="demoMode"><option value="true" ${state.settings.demoMode?'selected':''}>Enabled</option><option value="false" ${!state.settings.demoMode?'selected':''}>Disabled</option></select></div><div class="field full"><button class="btn btn-primary">Save Settings</button></div></form><div class="notice" style="margin-top:16px">For direct phone-camera QR testing, deploy the website to a public HTTPS URL and use that URL as the public base URL.</div></div></div>`);}
function initSettings(){document.getElementById('company-form')?.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);state.company.name=fd.get('name');state.company.location=fd.get('location');state.company.contact=fd.get('contact');state.company.email=fd.get('email');Object.values(state.packages).forEach(p=>{p.companyName=state.company.name;p.companyLocation=state.company.location;});saveState(state);showToast('Company profile saved','success');});document.getElementById('settings-form')?.addEventListener('submit',e=>{e.preventDefault();const fd=new FormData(e.currentTarget);state.settings.publicBaseUrl=String(fd.get('publicBaseUrl')||'').replace(/\/$/,'');state.settings.demoMode=fd.get('demoMode')==='true';saveState(state);showToast('Settings saved','success');});}

function simulateSensor(id){const p=state.packages[id];if(!p)return;const stages=['Fresh','Early Spoilage','Moderate Spoilage','High Indication'];let idx=stages.indexOf(p.status);idx=Math.min(stages.length-1,idx+1);const next=stages[idx];const prof=PRODUCT_PROFILES[p.productType];const base=next==='Fresh'?prof.idealTemp:next==='Early Spoilage'?prof.idealTemp+1.8:next==='Moderate Spoilage'?prof.idealTemp+3.2:prof.idealTemp+4.8;const vals=getStageValues(p.productType,next,base);p.monitoringStage=next;p.currentTemperature=vals.temperature;p.currentGasValue=vals.gas;p.currentPH=vals.pH;p.currentStickerColor=COLOR_FOR_STAGE[next];p.currentRGB=vals.rgb;p.freshnessScore=vals.freshness;p.spoilageIndex=100-vals.freshness;p.status=next;p.condition=vals.condition;p.contaminationLevel=vals.contamination;p.updatedAt=nowISO();p.sensorHistory.push({timestamp:p.updatedAt,temperature:p.currentTemperature,gasIndex:p.currentGasValue,pH:p.currentPH,stickerColor:p.currentStickerColor,freshnessScore:p.freshnessScore,spoilageIndex:p.spoilageIndex,status:p.status,condition:p.condition,contaminationLevel:p.contaminationLevel});saveState(state);showToast(`${p.productName}: ${p.currentStickerColor} · pH ${p.currentPH}`,'success');navigate('packages',id);}
function copyText(t){navigator.clipboard?.writeText(t).then(()=>showToast('Copied to clipboard','success')).catch(()=>prompt('Copy this link',t));}
function openReport(id){const p=state.packages[id];const w=window.open('','_blank');w.document.write(`<html><head><title>FreshTrace ${p.packageId}</title><style>body{font-family:Inter,Arial;padding:32px;color:#17212B}h1{color:#4B2A68}.grid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.box{border:1px solid #ddd;border-radius:12px;padding:15px;margin:10px 0}table{width:100%;border-collapse:collapse}td,th{border:1px solid #ddd;padding:8px;font-size:12px}</style></head><body><h1>FRESHTRACE BIO</h1><p>Smart Food Freshness Monitoring Report</p><div class="box"><strong>${esc(p.productName)}</strong><br/>Batch: ${esc(p.batchNumber)}<br/>Package: ${esc(p.packageId)}<br/>Company: ${esc(p.companyName)}</div><div class="grid"><div class="box">pH<br/><strong>${p.currentPH}</strong></div><div class="box">Temperature<br/><strong>${p.currentTemperature}°C</strong></div><div class="box">Gas Index<br/><strong>${p.currentGasValue}</strong></div><div class="box">Freshness<br/><strong>${p.freshnessScore}/100</strong></div></div><div class="box">Condition: <strong>${esc(p.condition)}</strong><br/>Sticker: ${esc(p.currentStickerColor)}<br/>Expected Expiry: ${fmtDate(p.expectedExpiryDate)}<br/>Storage: ${p.storageTemperature}°C</div><table><tr><th>Time</th><th>pH</th><th>Temp</th><th>Gas</th><th>Colour</th><th>Score</th></tr>${p.sensorHistory.map(h=>`<tr><td>${fmtDateTime(h.timestamp)}</td><td>${h.pH}</td><td>${h.temperature}</td><td>${h.gasIndex}</td><td>${h.stickerColor}</td><td>${h.freshnessScore}</td></tr>`).join('')}</table><script>window.onload=()=>window.print();<\/script></body></html>`);w.document.close();}
function resetDemo(){if(confirm('Reset to the FreshTrace demo packages?')){state=defaultState();saveState(state);showToast('Demo packages reset','success');navigate('dashboard');}}
function showModal(title,html){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><h3>${esc(title)}</h3><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body">${html}</div></div></div>`;}
function closeModal(){document.getElementById('modal-root').innerHTML='';}
function initChartsForPage(){const r=routeFromHash();if(r.route==='analytics')initAnalytics();if(r.route==='scan'&&r.id)initPublicCharts(state.packages[r.id]);if(r.route==='packages'&&r.id)initDetailCharts(state.packages[r.id]);}
function initDetailCharts(p){if(!p)return;setTimeout(()=>{drawLine(document.getElementById('detail-temp-chart'),p.sensorHistory.map(x=>x.temperature),'#2BE3D6');drawLine(document.getElementById('detail-ph-chart'),p.sensorHistory.map(x=>x.pH),'#C95BFF');const qr=document.getElementById('detail-qr');if(qr)wireStaticQr(qr,p,'detail-qr-fallback');},0);}
function initPublicCharts(p){if(!p)return;setTimeout(()=>{drawLine(document.getElementById('public-temp-chart'),p.sensorHistory.map(x=>x.temperature),'#2BE3D6');drawLine(document.getElementById('public-ph-chart'),p.sensorHistory.map(x=>x.pH),'#C95BFF');const qr=document.getElementById('public-qr');if(qr)wireStaticQr(qr,p,'public-qr-fallback');},0);}
function drawLine(el,vals,color){if(!el)return;if(!vals.length){el.innerHTML='<div class="placeholder">No data</div>';return;}const W=700,H=230,pad=28,min=Math.min(...vals),max=Math.max(...vals),range=max-min||1;const pts=vals.map((v,i)=>[pad+i*(W-pad*2)/Math.max(vals.length-1,1),H-pad-(v-min)/range*(H-pad*2)]);const path=`M${pts[0][0]} ${pts[0][1]} `+pts.slice(1).map(p=>`L${p[0]} ${p[1]}`).join(' ');el.innerHTML=`<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none"><line x1="${pad}" x2="${W-pad}" y1="${H-pad}" y2="${H-pad}" stroke="#E8E9EE"/>${[.25,.5,.75].map(t=>`<line x1="${pad}" x2="${W-pad}" y1="${pad+(H-pad*2)*t}" y2="${pad+(H-pad*2)*t}" stroke="#F0F1F4"/>`).join('')}<path d="${path}" fill="none" stroke="${color}" stroke-width="4" stroke-linecap="round"/><circle cx="${pts[pts.length-1][0]}" cy="${pts[pts.length-1][1]}" r="5" fill="${color}"/></svg>`;}

function renderApp(){state=loadState();const {route,id}=routeFromHash();document.body.classList.toggle('public-mode',route==='scan'&&!!id);const app=document.getElementById('app');if(route==='home')app.innerHTML=renderHome();else if(route==='dashboard')app.innerHTML=renderDashboard();else if(route==='register')app.innerHTML=renderRegister();else if(route==='packages')app.innerHTML=renderPackages(id);else if(route==='qr')app.innerHTML=renderQR();else if(route==='scan'&&id){const p=state.packages[id];if(p){app.innerHTML=renderPublic(p);p.scans=(p.scans||[]).concat([{time:nowISO()}]);state.packages[id]=p;saveState(state);}else app.innerHTML=renderNotFound();}else if(route==='scan')app.innerHTML=renderScan();else if(route==='analytics')app.innerHTML=renderAnalytics();else if(route==='research')app.innerHTML=renderResearch();else if(route==='settings')app.innerHTML=renderSettings();else app.innerHTML=renderNotFound();document.querySelectorAll('[data-route]').forEach(btn=>btn.onclick=()=>navigate(btn.dataset.route));if(route==='home')initHome();if(route==='register')initRegister();if(route==='packages'&&!id)initPackages();if(route==='qr')initQR();if(route==='scan'&&!id)initScanner();if(route==='settings')initSettings();initChartsForPage();}
function renderNotFound(){return layout('Page not found','The requested package or route does not exist.',`<div class="card pad"><div class="placeholder"><div><strong>Nothing to show here</strong><span>Return to Home or Dashboard.</span></div></div></div>`,'<button class="btn btn-primary" data-route="home">Back to Home</button>');}

document.getElementById('reset-demo')?.addEventListener('click',resetDemo);document.getElementById('notif-btn')?.addEventListener('click',()=>showModal('Notifications',state.notifications.length?state.notifications.slice(0,6).map(n=>`<div style="padding:10px 0;border-bottom:1px solid #e8eaee"><strong>${esc(n.message)}</strong><div class="muted" style="font-size:10px">${fmtDateTime(n.time)}</div></div>`).join(''):'<div class="placeholder"><div><strong>No notifications</strong><span>You are all caught up.</span></div></div>'));document.getElementById('profile-btn')?.addEventListener('click',()=>showModal('Profile',`<div class="kpi-row"><div class="kpi">Name<strong>${esc(state.profile.name)}</strong></div><div class="kpi">Role<strong>${esc(state.profile.role)}</strong></div></div>`));
window.addEventListener('hashchange',renderApp);window.addEventListener('load',()=>{if(!location.hash)location.hash='#home';else renderApp();});
renderApp();
window.navigate=navigate;window.copyText=copyText;window.openReport=openReport;window.simulateSensor=simulateSensor;window.closeModal=closeModal;
